const input = $input.first().json || {};

const response = input.response || {
  ok: false,
  status: 'file_error',
  reply: {
    type: 'text',
    text: 'حدث خطأ أثناء معالجة الملف. حاول إرسال PDF أو Word واضح.',
    buttons: [
      { label: '🏠 القائمة الرئيسية', action: 'MAIN_MENU' },
      { label: '❌ إلغاء', action: 'CANCEL' }
    ],
    file: null
  },
  data: {},
  error: 'file_processing_error'
};

return [
  {
    json: {
      ok: false,
      status: response.status || 'file_error',
      request: input.request,
      user: input.user,
      active_session: input.active_session,
      response,
      reply: response.reply || null,
      data: response.data || {},
      error: response.error || null
    }
  }
];

const input = $json;

let content =
  input.output ||
  input.text ||
  input.response ||
  input.message ||
  input.result ||
  input.chatOutput ||
  "";

if (typeof content === "object") {
  content =
    content.content ||
    content.text ||
    content.output ||
    content.response ||
    JSON.stringify(content);
}

if (typeof content !== "string") {
  content = JSON.stringify(content);
}

content = content.trim();

// Strip markdown code fences
if (content.startsWith("```")) {
  content = content
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();
}

// Extract first valid JSON object if there's surrounding text
const jsonStart = content.indexOf("{");
const jsonEnd   = content.lastIndexOf("}");
if (jsonStart !== -1 && jsonEnd !== -1 && jsonEnd > jsonStart) {
  content = content.slice(jsonStart, jsonEnd + 1);
}

let parsed;
try {
  parsed = JSON.parse(content);
} catch (e) {
  // Attempt to fix common trailing-comma issues
  const fixed = content
    .replace(/,\s*}/g, "}")
    .replace(/,\s*]/g, "]");
  parsed = JSON.parse(fixed);
}

return [{ json: parsed }];

const a = $json;

const meta = $('Build Analyze CV Agent Input').first().json || {};

const chatId =
  a.chatId ||
  a.chat_id ||
  meta.chatId ||
  "";

function bullets(arr, limit = 3) {
  return (arr || [])
    .slice(0, limit)
    .map(item => {
      if (typeof item === "string") {
        return `• ${item}`;
      }

      if (item.action) {
        return `• ${item.action}${item.reason ? ` — ${item.reason}` : ""}`;
      }

      return `• ${JSON.stringify(item)}`;
    })
    .join("\n");
}

const nextActionsText = (a.nextBestActions || [])
  .slice(0, 3)
  .map((x, i) => {
    if (typeof x === "string") {
      return `${i + 1}. ${x}`;
    }

    return `${x.priority || i + 1}. ${x.action || ""}${x.reason ? ` — ${x.reason}` : ""}`;
  })
  .filter(Boolean)
  .join("\n");

const detectedProfileLabel = a.detectedDomain
  ? String(a.detectedDomain).replace(/([A-Z])/g, " $1").trim()
  : "general";

const text = `✅ CV Analysis Completed

Overall Score: ${a.overallScore || 0}/100
ATS Score: ${a.atsScore || 0}/100
Recruiter Score: ${a.recruiterScore || 0}/100
Level: ${a.atsLevel || a.status || "N/A"}

Detected Profile:
${detectedProfileLabel}

Quick Summary:
${a.summary || "No summary available."}

Top Strengths:
${bullets(a.strengths, 3) || "No strengths detected."}

Key Weaknesses:
${bullets(a.weaknesses, 3) || "No major weaknesses detected."}

Suggested Keywords to Improve ATS:
${bullets(a.missingKeywords, 5) || "No suggested keywords available."}

Risk Flags:
${bullets(a.riskFlags, 3) || "No major risk flags detected."}

Next Best Actions:
${nextActionsText || "No next actions available."}
`;

return [
  {
    json: {
      ok: true,
      status: "cv_analyzed",
      chat_id: String(chatId || ""),

      reply: {
        type: "text",
        text,
        buttons: [
          {
            label: "🏠 Main Menu",
            action: "MAIN_MENU"
          }
        ],
        file: null
      },

      analysis: {
        ...a,
        chatId: String(chatId || ""),
        channel: a.channel || meta.channel || "telegram"
      }
    }
  }
];

const a = $json;

function levelFromScore(score) {
  score = Number(score || 0);

  if (score >= 90) return "Excellent";
  if (score >= 75) return "Very Good";
  if (score >= 60) return "Good";
  if (score >= 45) return "Fair";
  return "Poor";
}

function normalizeEducation(items) {
  return (items || []).map(e => ({
    degree: e.degree || e.qualification || "",
    institution: e.institution || "",
    year: e.year || e.endDate || "",
    gpa: e.gpa ?? null
  }));
}

function normalizeExperience(items) {
  return (items || []).map(e => ({
    role: e.role || "",
    company: e.company || "",
    duration: e.duration || [e.startDate, e.endDate].filter(Boolean).join(" – "),
    responsibilities: e.responsibilities || e.details || e.bullets || [],
    achievements: e.achievements || []
  }));
}

function normalizeProjects(items) {
  return (items || []).map(p => ({
    name: p.name || p.title || "",
    description: p.description || p.summary || "",
    technologies: p.technologies || (p.tech ? p.tech.split(",").map(x => x.trim()) : []),
    outcomes: p.outcomes ?? null
  }));
}

function normalizeNextBestActions(items) {
  return (items || []).slice(0, 3).map((x, i) => {
    if (typeof x === "string") {
      return {
        priority: i + 1,
        action: x,
        reason: ""
      };
    }

    return {
      priority: x.priority || i + 1,
      action: x.action || "",
      reason: x.reason || ""
    };
  });
}

function normalizeOptimizedExperience(items) {
  return (items || []).map(e => ({
    role: e.role || "",
    company: e.company || "",
    location: e.location ?? null,
    dates: e.dates || e.duration || "",
    bullets: e.bullets || e.responsibilities || []
  }));
}

function normalizeOptimizedProjects(items) {
  return (items || []).map(p => ({
    title: p.title || p.name || "",
    tech: p.tech || (Array.isArray(p.technologies) ? p.technologies.join(", ") : ""),
    summary: p.summary || p.description || ""
  }));
}

const atsScore = Number(a.atsScore || 0);
const recruiterScore = Number(a.recruiterScore || 0);
const jobMatchScore = Number(a.jobMatchScore || 0);

const hasJobContext = Boolean(a.targetRole || a.jobDescriptionProvided);

const calculatedOverall = hasJobContext
  ? Math.round((atsScore * 0.45) + (recruiterScore * 0.25) + (jobMatchScore * 0.30))
  : Math.round((atsScore * 0.70) + (recruiterScore * 0.30));

const overallScore = Number(a.overallScore || calculatedOverall);
const level = levelFromScore(overallScore);

let scoreBreakdown = {
  formattingAndStructure: Number(a.scoreBreakdown?.formattingAndStructure || 0),
  keywordOptimization: Number(a.scoreBreakdown?.keywordOptimization || 0),
  contentQuality: Number(a.scoreBreakdown?.contentQuality || 0),
  atsCompatibility: Number(a.scoreBreakdown?.atsCompatibility || 0)
};

const breakdownSum =
  scoreBreakdown.formattingAndStructure +
  scoreBreakdown.keywordOptimization +
  scoreBreakdown.contentQuality +
  scoreBreakdown.atsCompatibility;

// Safety correction فقط إذا المجموع لا يساوي ATS Score
if (breakdownSum !== atsScore) {
  const diff = atsScore - breakdownSum;
  scoreBreakdown.atsCompatibility = Math.max(
    0,
    scoreBreakdown.atsCompatibility + diff
  );
}

const normalized = {
  fileId: a.fileId || "",
  fileName: a.fileName || "",
  cvId: a.cvId ?? null,
  userId: a.userId ?? null,
  sessionId: a.sessionId ?? null,
  language: a.language || "en",
  targetRole: a.targetRole || "",
  jobDescriptionProvided: Boolean(a.jobDescriptionProvided),

  candidateName: a.candidateName ?? null,
  email: a.email ?? null,
  phone: a.phone ?? null,
  location: a.location ?? null,
  currentRole: a.currentRole ?? null,
  totalYearsExperience: Number(a.totalYearsExperience || 0),

  technicalSkills: a.technicalSkills || [],
  softSkills: a.softSkills || [],
  education: normalizeEducation(a.education),
  experience: normalizeExperience(a.experience),
  projects: normalizeProjects(a.projects),

  atsScore,
  recruiterScore,
  jobMatchScore,
  overallScore,
  atsLevel: level,
  status: level,

  scoreBreakdown,

  strengths: a.strengths || [],
  weaknesses: a.weaknesses || [],
  matchedKeywords: a.matchedKeywords || [],
  missingKeywords: a.missingKeywords || [],
  missingJobRequirements: a.missingJobRequirements || [],
  riskFlags: a.riskFlags || [],
  recommendations: a.recommendations || [],
  nextBestActions: normalizeNextBestActions(a.nextBestActions),

  summary: a.summary || "",
  matchSummary: a.matchSummary || "",

  optimizedOnePageCV: {
    headline: a.optimizedOnePageCV?.headline || "",
    professionalSummary: a.optimizedOnePageCV?.professionalSummary || "",
    skills: a.optimizedOnePageCV?.skills || [],
    experience: normalizeOptimizedExperience(a.optimizedOnePageCV?.experience),
    projects: normalizeOptimizedProjects(a.optimizedOnePageCV?.projects),
    education: a.optimizedOnePageCV?.education || [],
    languages: a.optimizedOnePageCV?.languages || []
  },

  coverLetterDraft: a.coverLetterDraft || ""
};

return [{ json: normalized }];

const analysis = $json;

// نجيب البيانات الأصلية من Node قبل AI
const meta = $('Build Analyze CV Agent Input').first().json || {};

const fixed = {
  ...analysis,

  fileId: analysis.fileId || meta.fileId || "",
  fileName: analysis.fileName || meta.fileName || "",
  cvId: analysis.cvId ?? meta.cvId ?? null,
  userId: analysis.userId ?? meta.userId ?? null,
  sessionId: analysis.sessionId ?? meta.sessionId ?? null,

  channel: analysis.channel || meta.channel || "telegram",
  chatId: analysis.chatId || meta.chatId || "",

  language: analysis.language || meta.language || "en",
  targetRole: analysis.targetRole || meta.targetRole || "",
  jobDescriptionProvided: Boolean(
    analysis.jobDescriptionProvided ||
    (meta.jobDescription && meta.jobDescription.trim().length > 0)
  )
};

return [
  {
    json: fixed
  }
];

// ============================================================
// SmartATS — Validate And Fix Analysis v4
// Purpose:
// - Enforce strict ATS / recruiter scoring realism
// - Preserve metadata such as chatId
// - Clean missingKeywords from advice phrases
// - Detect career domain
// - Ensure scoreBreakdown sums exactly to atsScore
// ============================================================

const a = $json;

// Get original metadata from the node before AI
const meta = $('Build Analyze CV Agent Input').first().json || {};

// ─────────────────────────────────────────────
// 1. IDENTITY / METADATA
// ─────────────────────────────────────────────

const resolvedChatId = String(
  a.chatId ||
  a.chat_id ||
  meta.chatId ||
  ""
);

const resolvedChannel =
  a.channel ||
  meta.channel ||
  "telegram";

const resolvedLanguage =
  a.language ||
  meta.language ||
  "en";

const resolvedTargetRole =
  a.targetRole ||
  meta.targetRole ||
  "";

const jobDescriptionProvided = Boolean(
  a.jobDescriptionProvided ||
  (meta.jobDescription && String(meta.jobDescription).trim().length > 0)
);

const hasJobContext = Boolean(resolvedTargetRole || jobDescriptionProvided);

// ─────────────────────────────────────────────
// 2. UTILITIES
// ─────────────────────────────────────────────

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, Number(value) || 0));
}

function levelFromScore(score) {
  score = Number(score) || 0;

  if (score >= 90) return "Excellent";
  if (score >= 75) return "Very Good";
  if (score >= 60) return "Good";
  if (score >= 45) return "Fair";
  return "Poor";
}

function norm(value) {
  return String(value || "")
    .toLowerCase()
    .trim()
    .replace(/\s+/g, " ");
}

function uniqueStr(arr) {
  const seen = new Set();

  return (arr || [])
    .map(x => String(x || "").trim())
    .filter(Boolean)
    .filter(x => {
      const key = x.toLowerCase();

      if (seen.has(key)) {
        return false;
      }

      seen.add(key);
      return true;
    });
}

function includesAny(text, list) {
  const normalizedText = norm(text);
  return list.some(item => normalizedText.includes(norm(item)));
}

// ─────────────────────────────────────────────
// 3. BUILD FULL CV TEXT FOR ALL CHECKS
// Priority: meta.cvText raw text → extracted AI fields
// ─────────────────────────────────────────────

const rawCvText = norm(
  meta.cvText ||
  meta.cvtext ||
  ""
);

const profileText = norm([
  rawCvText,
  a.currentRole || "",
  a.summary || "",
  resolvedTargetRole,

  ...(a.technicalSkills || []),
  ...(a.softSkills || []),

  ...(a.education || []).map(e =>
    `${e.degree || ""} ${e.institution || ""} ${e.year || ""}`
  ),

  ...(a.experience || []).map(e =>
    `${e.role || ""} ${e.company || ""} ${e.duration || ""} ${(e.responsibilities || []).join(" ")} ${(e.achievements || []).join(" ")}`
  ),

  ...(a.projects || []).map(p =>
    `${p.name || ""} ${p.description || ""} ${(p.technologies || []).join(" ")} ${p.outcomes || ""}`
  )
].join(" "));

// ─────────────────────────────────────────────
// 4. CV CHARACTERISTIC FLAGS
// ─────────────────────────────────────────────

function hasMetricEvidence(text) {
  const t = String(text || "").toLowerCase();

  const metricPatterns = [
    /\d+\s*%/,
    /\d+\s*(users|customers|clients|students|patients|projects|features|pages|reports|cases|tickets|orders|transactions|requests|employees|hours|days|weeks|months)/,
    /\d+\s*(jod|usd|eur|dollars|revenue|sales)/,
    /(increased|reduced|improved|optimized|decreased|saved|grew|boosted)\s+.*\d+/,
    /(lighthouse|performance|conversion|retention|satisfaction|csat|kpi|score|rating)\s+.*\d+/
  ];

  return metricPatterns.some(pattern => pattern.test(t));
}

const hasMeasurable = hasMetricEvidence(profileText);

const hasExperience =
  (a.experience || []).length > 0 ||
  (a.projects || []).length > 0 ||
  includesAny(profileText, [
    "intern",
    "freelance",
    "volunteer",
    "training",
    "practical",
    "worked",
    "experience",
    "project"
  ]);

const hasProjects = (a.projects || []).length > 0;

const projectsHaveOutcomes = (a.projects || []).some(project => {
  const outcome = String(project.outcomes || "").trim();
  const description = String(project.description || "").trim();

  return Boolean(outcome) || hasMetricEvidence(description);
});

const experienceText = norm(
  (a.experience || [])
    .map(e =>
      `${e.role || ""} ${(e.responsibilities || []).join(" ")} ${(e.achievements || []).join(" ")}`
    )
    .join(" ")
);

const hasClearContribution = includesAny(experienceText, [
  "built",
  "developed",
  "implemented",
  "designed",
  "delivered",
  "managed",
  "created",
  "trained",
  "analyzed",
  "coordinated",
  "improved",
  "integrated",
  "led",
  "prepared",
  "supported",
  "planned",
  "reported"
]);

const summaryText = norm(a.summary || "");

const isGenericSummary =
  summaryText.length < 120 ||
  includesAny(summaryText, [
    "strong foundation",
    "various technologies",
    "hardworking",
    "motivated",
    "passionate",
    "good communication",
    "team player"
  ]);

const isEarlyCareer = includesAny(
  [
    a.currentRole,
    a.summary,
    ...(a.education || []).map(e => e.degree || ""),
    ...(a.experience || []).map(e => e.role || "")
  ].join(" "),
  [
    "student",
    "intern",
    "trainee",
    "junior",
    "fresh graduate",
    "entry level",
    "entry-level"
  ]
);

// ─────────────────────────────────────────────
// 5. SCORE BREAKDOWN REPAIR
// ─────────────────────────────────────────────

const LIMITS = {
  formattingAndStructure: 20,
  keywordOptimization: 25,
  contentQuality: 30,
  atsCompatibility: 25
};

let b = a.scoreBreakdown || {};

b = {
  formattingAndStructure: clamp(
    b.formattingAndStructure,
    0,
    LIMITS.formattingAndStructure
  ),

  keywordOptimization: clamp(
    b.keywordOptimization,
    0,
    LIMITS.keywordOptimization
  ),

  contentQuality: clamp(
    b.contentQuality,
    0,
    LIMITS.contentQuality
  ),

  atsCompatibility: clamp(
    b.atsCompatibility,
    0,
    LIMITS.atsCompatibility
  )
};

// ─────────────────────────────────────────────
// 6. HARD SCORE CAP ENFORCEMENT
// ─────────────────────────────────────────────

let atsScore = clamp(a.atsScore, 0, 100);

// Strict ATS caps
if (!hasMeasurable && atsScore > 72) {
  atsScore = 72;
}

if (hasProjects && !projectsHaveOutcomes && atsScore > 72) {
  atsScore = 72;
}

if (!hasClearContribution && atsScore > 70) {
  atsScore = 70;
}

if (isGenericSummary && atsScore > 75) {
  atsScore = 75;
}

if (isEarlyCareer && !hasMeasurable && atsScore > 74) {
  atsScore = 74;
}

if (!hasExperience && atsScore > 65) {
  atsScore = 65;
}

// Recruiter score caps
let recruiterScore = clamp(a.recruiterScore, 0, 100);

if (!hasMeasurable && recruiterScore > 76) {
  recruiterScore = 76;
}

if (hasProjects && !projectsHaveOutcomes && recruiterScore > 75) {
  recruiterScore = 75;
}

if (isGenericSummary && recruiterScore > 75) {
  recruiterScore = 75;
}

if (isEarlyCareer && !hasMeasurable && recruiterScore > 76) {
  recruiterScore = 76;
}

// Job match
const jobMatchScore = hasJobContext
  ? clamp(a.jobMatchScore, 0, 100)
  : 0;

// ─────────────────────────────────────────────
// 7. SYNC scoreBreakdown WITH atsScore
// ─────────────────────────────────────────────

let sumB =
  b.formattingAndStructure +
  b.keywordOptimization +
  b.contentQuality +
  b.atsCompatibility;

if (sumB > 0 && atsScore < sumB) {
  const ratio = atsScore / sumB;

  b = {
    formattingAndStructure: Math.floor(b.formattingAndStructure * ratio),
    keywordOptimization: Math.floor(b.keywordOptimization * ratio),
    contentQuality: Math.floor(b.contentQuality * ratio),
    atsCompatibility: Math.floor(b.atsCompatibility * ratio)
  };
}

// Distribute rounding difference to score with most flexibility
let diff =
  atsScore -
  (
    b.formattingAndStructure +
    b.keywordOptimization +
    b.contentQuality +
    b.atsCompatibility
  );

if (diff !== 0) {
  const order = [
    "contentQuality",
    "atsCompatibility",
    "keywordOptimization",
    "formattingAndStructure"
  ];

  for (const key of order) {
    const room =
      diff > 0
        ? LIMITS[key] - b[key]
        : b[key];

    const add =
      diff > 0
        ? Math.min(diff, room)
        : Math.max(diff, -room);

    b[key] = clamp(b[key] + add, 0, LIMITS[key]);
    diff -= add;

    if (diff === 0) {
      break;
    }
  }

  const finalSum =
    b.formattingAndStructure +
    b.keywordOptimization +
    b.contentQuality +
    b.atsCompatibility;

  if (finalSum !== atsScore) {
    atsScore = finalSum;
  }
}

// ─────────────────────────────────────────────
// 8. OVERALL SCORE
// ─────────────────────────────────────────────

const overallScore = hasJobContext
  ? Math.round(
      atsScore * 0.45 +
      recruiterScore * 0.25 +
      jobMatchScore * 0.30
    )
  : Math.round(
      atsScore * 0.70 +
      recruiterScore * 0.30
    );

const level = levelFromScore(overallScore);

// ─────────────────────────────────────────────
// 9. DOMAIN DETECTION
// ─────────────────────────────────────────────

function detectDomain(text) {
  if (includesAny(text, [
    "react",
    "frontend",
    "front-end",
    "html",
    "css",
    "javascript",
    "tailwind",
    "bootstrap",
    "next.js",
    "vue",
    "angular",
    "ui component"
  ])) {
    return "frontend";
  }

  if (includesAny(text, [
    "backend",
    "back-end",
    "node.js",
    "express",
    "django",
    "asp.net",
    "spring",
