function isAdvice(keyword) {
  const normalized = norm(keyword);

  if (!normalized) {
    return true;
  }

  if (normalized.split(" ").length > 5) {
    return true;
  }

  return ADVICE_PHRASES.some(phrase =>
    normalized === norm(phrase) ||
    normalized.includes(norm(phrase))
  );
}

