function isInCV(keyword) {
  const normalizedKeyword = norm(keyword);

  if (!normalizedKeyword) {
    return true;
  }

  if (rawCvText && rawCvText.length > 10 && rawCvText.includes(normalizedKeyword)) {
    return true;
  }

  if (profileText.includes(normalizedKeyword)) {
    return true;
  }

  const relatedTerms = SEMANTIC_PRESENT[normalizedKeyword] || [];

  return relatedTerms.some(term =>
    profileText.includes(norm(term)) ||
    rawCvText.includes(norm(term))
  );
}

