  const words = norm(action).split(" ");

  return (
    words.length < 8 ||
    WEAK_VERBS.some(verb =>
      words[0] === verb && words.length < 10
    )
  );
}

const FALLBACK_ACTIONS = [
  {
    priority: 1,
    action: "Rewrite each project description in the Projects section to include at least one measurable outcome such as performance improvement percentage, Lighthouse score, number of users, or API response time.",
    reason: "Quantified results are the strongest ATS and recruiter score improvement because missing metrics are the main reason this CV cannot score above the strict cap."
  },
  {
    priority: 2,
    action: "Rewrite the Professional Summary to name the strongest technical skill, one signature project, and the specific role target in three concise sentences.",
    reason: "A generic summary reduces relevance scoring and fails to differentiate the candidate during the first recruiter review."
  },
  {
    priority: 3,
    action: `Add missing domain keywords such as ${missingKeywords.slice(0, 3).join(", ")} to the Skills section if the candidate genuinely has these skills.`,
    reason: "ATS systems filter candidates by keyword presence before human review, so targeted keywords improve initial screening performance."
  }
];

function normalizeActions(items) {
  const arr = Array.isArray(items) ? items : [];

  const fixed = arr.slice(0, 3).map((item, index) => {
    if (typeof item === "string") {
      return {
        priority: index + 1,
        action: item,
        reason: ""
      };
    }

    return {
      priority: Number(item.priority) || index + 1,
      action: String(item.action || "").trim(),
      reason: String(item.reason || "").trim()
    };
  });

  fixed.forEach((item, index) => {
    if (!item.action || isWeakAction(item.action)) {
      fixed[index] = FALLBACK_ACTIONS[index];
    }
  });

  while (fixed.length < 3) {
    fixed.push(FALLBACK_ACTIONS[fixed.length]);
  }

  return fixed
    .slice(0, 3)
    .map((item, index) => ({
      ...item,
      priority: index + 1
    }));
}

